<script setup lang="ts">
import{Head,router}from'@inertiajs/vue3';import{computed,onBeforeUnmount,onMounted,ref}from'vue';
const props=defineProps<{attempt:any;exam:any;questions:any[]}>();const answers=ref<Record<number,string>>(Object.fromEntries(props.questions.map(q=>[q.id,q.answer??''])));const now=ref(Date.now());let timer:number|undefined,heartbeat:number|undefined;
const remaining=computed(()=>Math.max(0,Math.floor((new Date(props.attempt.expires_at).getTime()-now.value)/1000)));const clock=computed(()=>`${Math.floor(remaining.value/60)}:${String(remaining.value%60).padStart(2,'0')}`);
const save=(id:number)=>router.put(`/ujian/attempt/${props.attempt.id}/jawaban`,{question_id:id,answer:answers.value[id]},{preserveScroll:true,preserveState:true});const violation=(type:string)=>router.post(`/ujian/attempt/${props.attempt.id}/pelanggaran`,{type},{preserveScroll:true});const visibility=()=>{if(document.hidden)violation('tab_hidden')};
const submitExam=()=>{if(window.confirm('Kirim jawaban sekarang?'))router.post(`/ujian/attempt/${props.attempt.id}/kirim`)};
onMounted(()=>{timer=window.setInterval(()=>{now.value=Date.now();if(!remaining.value)router.post(`/ujian/attempt/${props.attempt.id}/kirim`)},1000);heartbeat=window.setInterval(()=>router.post(`/ujian/attempt/${props.attempt.id}/heartbeat`,{},{preserveState:true}),30000);document.addEventListener('visibilitychange',visibility)});onBeforeUnmount(()=>{clearInterval(timer);clearInterval(heartbeat);document.removeEventListener('visibilitychange',visibility)});
</script>
<template><Head :title="exam.title"/><main class="exam-shell"><header><div><p>UJIAN CBT</p><h1>{{ exam.title }}</h1></div><div class="timer">{{ clock }}</div></header><div v-if="attempt.status!=='in_progress'" class="notice">Attempt telah {{ attempt.status }}. Nilai akan tersedia setelah proses koreksi.</div><section><article v-for="(q,i) in questions" :key="q.id"><h2>{{ i+1 }}. {{ q.prompt }} <small>{{ q.points }} poin</small></h2><div v-if="q.type==='multiple_choice'" class="options"><label v-for="o in q.options" :key="o"><input v-model="answers[q.id]" type="radio" :value="o" :disabled="attempt.status!=='in_progress'" @change="save(q.id)">{{ o }}</label></div><textarea v-else v-model="answers[q.id]" rows="6" :disabled="attempt.status!=='in_progress'" @blur="save(q.id)" placeholder="Tulis jawaban esai"></textarea></article></section><footer><span>Pelanggaran {{ attempt.violation_count }}/{{ exam.max_violations }}</span><button v-if="attempt.status==='in_progress'" @click="submitExam">Kirim jawaban</button><a v-else href="/ujian">Kembali</a></footer></main></template>
<style scoped>.exam-shell{min-height:100vh;background:#f8fafc;color:#0f172a}.exam-shell header{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;padding:1rem 5vw;background:#fff;border-bottom:1px solid #e2e8f0}.exam-shell header p{font-size:.7rem;color:#4f46e5;font-weight:800}.exam-shell h1{font-size:1.25rem;font-weight:800}.timer{font-size:1.5rem;font-weight:900;color:#dc2626}section{max-width:850px;margin:auto;padding:2rem 1rem 7rem;display:grid;gap:1rem}article{padding:1.25rem;background:#fff;border:1px solid #e2e8f0;border-radius:1rem}article h2{font-weight:750}article small{float:right;color:#64748b}.options{display:grid;gap:.6rem;margin-top:1rem}.options label{padding:.7rem;border:1px solid #e2e8f0;border-radius:.7rem}.options input{margin-right:.6rem}textarea{width:100%;margin-top:1rem;padding:.8rem;border:1px solid #cbd5e1;border-radius:.7rem}.exam-shell footer{position:fixed;bottom:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:1rem 5vw;background:#fff;border-top:1px solid #e2e8f0}.exam-shell footer button,.exam-shell footer a{padding:.7rem 1rem;border-radius:.7rem;background:#4f46e5;color:white;font-weight:800}.notice{max-width:850px;margin:1rem auto;padding:1rem;background:#fff7ed;color:#9a3412}</style>
